% Knowledge base entry point.
%
%   engine.pl      inference engine: forward chaining, backward chaining with MYCIN CFs
%   metrics.pl     base facts, metric definitions, evidence requirements
%   thresholds.pl  generated by calibration (clean matches only)
%   symptoms.pl    LAYER 1: metrics -> symptoms         (forward)
%   diagnosis.pl   LAYER 2: symptoms -> diagnoses + CF  (backward)
%   actions.pl     LAYER 3: diagnosis -> action          (decision making / support)
%   explain.pl     how / why explanations

:- dynamic threshold/3.     % threshold(Metric, Percentile, Value)

:- ensure_loaded(engine).
:- ensure_loaded(metrics).
:- ensure_loaded(symptoms).
:- ensure_loaded(diagnosis).
:- ensure_loaded(actions).
:- ensure_loaded(explain).

:- prolog_load_context(directory, Dir),
   atom_concat(Dir, '/thresholds.pl', F),
   ( exists_file(F) -> consult(F) ; true ).

kb_ready.
